--- a/src/core/trust/slop.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/src/core/trust/slop.ts	2026-11-04 07:12:55.467689327 +0000
@@ -0,0 +1,75 @@
+import type { SessionEvent } from '../types.ts';
+
+// The slop check reads what a run changed and flags shortcuts that make work look done. It is a reminder and a
+// receipt flag, never a refusal: a finding can be right, and the report says why.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Rule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type Finding = { rule: Rule; path: string; line?: string };
+
+const CODE = /\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs|rb|java|kt|cs|swift|c|h|cc|cpp|php|sh)$/;
+const TEST = /(^|\/)(tests?|__tests__)\/|\.(test|spec)\.|_test\.|(^|\/)test_/;
+const ASSERT = /\bassert|\bexpect\(/;
+const SKIP = /\.skip\(|\bxit\(|\bxdescribe\(|\.Skip\(|pytest\.mark\.skip|pytest\.skip\(/;
+const LINE_RULES: [Rule, RegExp][] = [
+  ['suppression', /@ts-ignore|@ts-expect-error|eslint-disable|# type: ignore|# noqa|# pylint: disable|\/\/ nolint|#\[allow\(/],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|except\b[^:]*:\s*pass\b/],
+  ['type-escape', /\bas any\b|:\s*any\b|<any>/],
+  ['stub', /not implemented|NotImplementedError|todo!\(|unimplemented!\(/i],
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    if (!CODE.test(c.path)) continue;
+    const test = TEST.test(c.path);
+    if (test && c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    if (test && !c.deleted && c.added.filter((l) => ASSERT.test(l)).length < c.removed.filter((l) => ASSERT.test(l)).length)
+      out.push({ rule: 'test-weakened', path: c.path });
+    for (const raw of c.added) {
+      const line = raw.trim();
+      if (test && SKIP.test(line)) out.push({ rule: 'test-skipped', path: c.path, line });
+      for (const [rule, re] of LINE_RULES) if (re.test(line)) out.push({ rule, path: c.path, line });
+    }
+  }
+  return out;
+}
+
+export const flagOf = (f: Finding) => `${f.rule} ${f.path}${f.line === undefined ? '' : `: ${f.line}`}`;
+
+export const slopReminder = (flags: string[]) =>
+  `cedia's slop check found shortcuts in this run's changes: ${flags.join('; ')}. Each one can make work look done without being done. Fix what is not right; if one is right, say so in your report and why. The check is off with --unlock slop-check.`;
+
+// Reads a `git diff-tree -p -U0` patch: one FileChange per file, with the lines each hunk added or removed.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk) {
+      if (line.startsWith('deleted file mode')) cur.deleted = true;
+    } else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots, the changes are the edit and write calls that completed.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const done = new Set(events.flatMap((e) => (e.kind === 'tool_result' && e.status === 'completed' ? [e.callId] : [])));
+  const lines = (s: unknown) => String(s ?? '').split('\n');
+  return events.flatMap((e): FileChange[] => {
+    if (e.kind !== 'tool_intent' || !done.has(e.callId)) return [];
+    const path = String(e.input.path);
+    if (e.tool === 'write') return [{ path, added: lines(e.input.content), removed: [], deleted: false }];
+    if (e.tool !== 'edit') return [];
+    const edits = (e.input.edits as { old_text: string; new_text: string }[] | undefined) ?? [];
+    return [{ path, added: edits.flatMap((x) => lines(x.new_text)), removed: edits.flatMap((x) => lines(x.old_text)), deleted: false }];
+  });
+}
