+import type { EventOf, SessionEvent } from '../types.ts';
+
+// What a run changed, as lines. It comes from the shadow-git patch when snapshots are on, else from the edit and write calls.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type Finding = { rule: SlopRule; path: string; detail?: string };
+
+const TEST_PATH = /(\.test\.|\.spec\.|_test\.|(^|\/)test_[^/]*$|(^|\/)tests?\/|(^|\/)__tests__\/)/;
+const CODE_PATH = /\.(m?[jt]sx?|py|go|rs|rb|java|kt|cs|c|cc|cpp|h|hpp|swift|php|sh)$/;
+const ASSERT = /\bassert\w*|\bexpect\(|\bt\.(?:Fatal|Error)f?\(/;
+const SKIP = /\.skip\(|\bxit\(|\bxdescribe\(|\bxtest\(|\bt\.Skip(?:f|Now)?\(|@pytest\.mark\.skip|@unittest\.skip/;
+// Line rules run on added lines of code files only, in this order for each line.
+const LINE_RULES: [SlopRule, RegExp][] = [
+  ['suppression', /@ts-(?:ignore|expect-error|nocheck)|eslint-disable|# type: ignore|# noqa|# pylint: disable|#\[allow\(|nolint/],
+  ['swallowed-error', /\bcatch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\b/],
+  ['type-escape', /\bas any\b|<any>/],
+  ['stub', /\bnot implemented\b|NotImplementedError|\bunimplemented!\(|\btodo!\(/i],
+];
+
+const lines = (s: string) => s.split('\n');
+
+// Reads a `git diff -U0` patch. Only the hunk lines count: the --- and +++ headers are not changes.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of lines(patch)) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots: what the completed edit and write calls of this run asked for.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const out: FileChange[] = [];
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  for (const e of events) {
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    const path = String(intent?.input.path ?? '');
+    if (intent?.tool === 'write') out.push({ path, added: lines(String(intent.input.content ?? '')), removed: [], deleted: false });
+    else if (intent?.tool === 'edit') {
+      const edits = (intent.input.edits ?? []) as { old_text: string; new_text: string }[];
+      out.push({ path, added: edits.flatMap((x) => lines(x.new_text)), removed: edits.flatMap((x) => lines(x.old_text)), deleted: false });
+    }
+  }
+  return out;
+}
+
+// Shortcuts that make work look done. Each finding is a flag the receipt carries; none of them refuses a claim.
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    const isTest = TEST_PATH.test(c.path);
+    if (isTest && c.deleted) {
+      out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (isTest) {
+      if (c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length) out.push({ rule: 'test-weakened', path: c.path });
+      if (c.added.some((l) => SKIP.test(l))) out.push({ rule: 'test-skipped', path: c.path });
+    }
+    if (!CODE_PATH.test(c.path)) continue;
+    for (const line of c.added)
