+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('bulk discount starts at exactly 10 units', () => {
+    // 10 mugs = 4500; 5% off = 225; subtotal 4275; shipping 800; tax 7% of 5075 = 355
+    expect(totals(cart('US', [['MUG', 10]]))).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('bulk discount is 10% from exactly 50 units', () => {
+    // 50 pens = 6000; 10% off = 600; subtotal 5400 ships free; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same sku are merged before the bulk tier is chosen', () => {
+    // 6 + 5 pens = 11 units -> 5% of 1320 = 66; subtotal 1254; shipping 800; tax 7% of 2054 = 144
+    expect(totals(cart('US', [['PEN', 6], ['PEN', 5]]))).toMatchObject({ subtotal: 1254, shipping: 800, tax: 144, total: 2198 });
+  });
+
+  test('shipping is decided on the subtotal after the coupon', () => {
+    // 2200 + 2*1200 + 450 = 5050; SAVE10 takes 505 -> 4545 is under 5000, so shipping is charged
+    // tax 7% of 5345 = 374
+    expect(totals(cart('US', [['BAG', 1], ['CAP', 2], ['MUG', 1]], 'SAVE10'))).toMatchObject({
+      subtotal: 5050,
+      coupon: 505,
+      shipping: 800,
+      tax: 374,
+      total: 5719,
+    });
+  });
+
+  test('UK ships free from 4000', () => {
+    // 2200 + 1200 + 5*120 = 4000; shipping 0; tax 20% of 4000 = 800
+    expect(totals(cart('UK', [['BAG', 1], ['CAP', 1], ['PEN', 5]]))).toMatchObject({ subtotal: 4000, shipping: 0, tax: 800, total: 4800 });
+  });
+});

