+  const { cache, log, advance } = setup(2, 100);
+  cache.set('a', 1);
+  advance(50);
+  cache.set('b', 2);
+  advance(60); // a expired, b live
+  cache.set('c', 3);
+  expect(log).toEqual(['a=1:expired']);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});
+
+test('expired entry found by get is removed with reason expired', () => {
+  const { cache, log, advance } = setup(2, 100);
+  cache.set('a', 1);
+  advance(100);
+  expect(cache.get('a')).toBeUndefined();
+  expect(log).toEqual(['a=1:expired']);
